private void pop(final String descriptor){
    int index = 0;
    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor, find the end of the argument types
        while (descriptor.charAt(index) != ')') {
            index = popType(descriptor, index);
        }
        index++; // Move past the ')'
    }
    // Pop the return type if it's not void
    if (index < descriptor.length() && descriptor.charAt(index) != 'V') {
        popType(descriptor, index);
    }
}

