        if (c == '\\') {
            if (++i >= len) {
                throw new Exception("Invalid escape sequence");
            }
            c = str.charAt(i);
            switch (c) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
